#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

typedef struct Node { int value; struct Node *next; } Node;
typedef struct { Node *head,*tail; } Queue;
static int push(Queue *q,int value){
    Node *node=malloc(sizeof *node);if(!node)return 0;
    *node=(Node){value,NULL};
    if(q->tail)q->tail->next=node;else q->head=node;
    q->tail=node;return 1;
}
static int pop(Queue *q,int *out){
    if(!q->head)return 0;
    Node *old=q->head;*out=old->value;q->head=old->next;
    if(!q->head)q->tail=NULL;
    free(old);return 1;
}
static void destroy(Queue *q){int value;while(pop(q,&value)){} }
int main(void) {
Queue queue={0};int q,failed=0;if(scanf("%d",&q)!=1||q<0||q>128)return 1;for(int i=0;i<q;++i){char c;int x;if(scanf(" %c",&c)!=1){failed=1;break;}if(c=='P'){if(scanf("%d",&x)!=1||!push(&queue,x)){failed=1;break;}}else if(c=='O'){if(pop(&queue,&x))printf("%d\n",x);else puts("ПУСТО");}else{failed=1;break;}}destroy(&queue);if(failed)return 1;
return 0;
}
